python3 << 'EOF'
import urllib.request
import json
import urllib.parse

def search_crossref(query):
    try:
        query_encoded = urllib.parse.quote(query)
        url = f"https://api.crossref.org/works?query={query_encoded}&rows=5"
        with urllib.request.urlopen(url) as response:
            data = json.loads(response.read())
            if data['message']['items']:
                item = data['message']['items'][0]
                return {
                    'found': True,
                    'title': item.get('title', [''])[0],
                    'year': item.get('issued', {}).get('date-parts', [[None]])[0][0],
                    'type': item.get('type', 'unknown'),
                }
            return {'found': False}
    except Exception as e:
        return {'found': False, 'error': str(e)}

# Check books and remaining entries
remaining_citations = [
    ('Alberts Bruce Molecular Biology Cell 2014', 'Alberts2014'),
    ('Sambrook Joseph Molecular Cloning Laboratory Manual 2001', 'Sambrook2001'),
    ('Vaswani Ashish Attention All You Need NeurIPS 2017', 'Vaswani2017'),
]

print("VERIFYING BOOKS AND REMAINING MAJOR CITATIONS:\n")
for query, bibtex_key in remaining_citations:
    result = search_crossref(query)
    status = "VERIFIED" if result['found'] else "NOT VERIFIED"
    print(f"{bibtex_key}: {status}")
    if result['found']:
        print(f"  Year: {result['year']}, Type: {result['type']}")
        print(f"  Title: {result['title'][:70]}")

EOF
